package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimStore store, Out<Claim> claimOut) throws InvalidSheetException {
        Claim claim = null;
        try {
            claim = store.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            // not an id: no such claim
        }
        if (claim == null) {
            throw new InvalidSheetException("No such claim: " + claimId);
        }
        claimOut.set(claim);
    }
}
=== CheckRemind
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Refuses reminding a claim that is not OPEN or PENDING, or one already reminded on the sheet's today. */
public class CheckRemind {
    public void check(@Val Claim claim, SheetStore sheets) throws InvalidSheetException {
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new InvalidSheetException("Only an OPEN or PENDING claim can be reminded");
        }
        LocalDate today = sheets.today(claim.getSheetId());
        if (today.equals(claim.getRemindedOn())) {
            throw new InvalidSheetException("The claim was already reminded on " + today);
        }
    }
}
=== ApplyRemind
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Stores the claim reminded on the sheet's today; refused when another user moved it on or reminded it first. */
public class ApplyRemind {
    public void apply(@Val Claim claim, ClaimStore store, SheetStore sheets) throws InvalidSheetException {
        if (!store.remind(claim, sheets.today(claim.getSheetId()))) {
            throw new InvalidSheetException("Only an OPEN or PENDING claim not yet reminded today can be reminded");
        }
    }
}
