package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each claim's status log, oldest first: a line per status it has had,
 *  {@code <STATUS> by <user> on <sheet's today> due=<due as computed then, n/a when no rate applied>}. */
@Repository
public class ClaimLogStore {

    private final JdbcTemplate jdbc;
    private final ClaimStore claims;
    private final PersonStore people;
    private final RateStore rates;
    private final SettingStore settings;
    private final SheetStore sheets;

    public ClaimLogStore(JdbcTemplate jdbc, ClaimStore claims, PersonStore people, RateStore rates,
            SettingStore settings, SheetStore sheets) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Logs the claim's current status, by the user, on the sheet's today, at its due as the screen
     *  works it out now (its settled due once settled, else its figure plus any late charge). */
    public void record(Claim claim, String user) {
        String sheetId = claim.getSheetId();
        LocalDate today = sheets.today(sheetId);
        Person person = people.find(sheetId, claim.getPersonId());
        BigDecimal pct = person == null ? null
                : rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(sheetId, settings, sheets, claims, people).due(claim, pct);
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, claim.getId(), claim.getStatus().name(), user, Date.valueOf(today),
                due == null ? "n/a" : due.setScale(2).toPlainString());
    }

    /** Every claim's log lines on the sheet, by claim id, oldest first. */
    public Map<Long, List<String>> lines(String sheetId) {
        return lines(sheetId, null);
    }

    /** Every claim's log lines on the sheet logged on or before the date (all of them when it is null), by
     *  claim id, oldest first. */
    public Map<Long, List<String>> lines(String sheetId, LocalDate until) {
        Map<Long, List<String>> lines = new HashMap<>();
        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? AND (CAST(? AS DATE) IS NULL OR log_date <= ?) ORDER BY id", rs -> {
            lines.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + rs.getObject("log_date", LocalDate.class) + " due=" + rs.getString("due"));
        }, sheetId, until == null ? null : Date.valueOf(until), until == null ? null : Date.valueOf(until));
        return lines;
    }

    /** Each claim's status at the end of the date, by claim id, as its log records it: the last status
     *  logged on or before the date. A claim logged only after it (added after it) is absent. */
    public Map<Long, ClaimStatus> statusesAt(String sheetId, LocalDate date) {
        Map<Long, ClaimStatus> statuses = new HashMap<>();
        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND log_date <= ? ORDER BY id", rs -> {
            statuses.put(rs.getLong("claim_id"), ClaimStatus.valueOf(rs.getString("status")));
        }, sheetId, Date.valueOf(date));
        return statuses;
    }

    /** The sheet's today on which the claim was last logged SETTLED; null when it never was. */
    public LocalDate settledOn(Claim claim) {
        List<LocalDate> dates = jdbc.query("SELECT log_date FROM claim_log WHERE sheet_id = ? AND claim_id = ? "
                + "AND status = ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("log_date", LocalDate.class),
                claim.getSheetId(), claim.getId(), ClaimStatus.SETTLED.name());
        return dates.isEmpty() ? null : dates.get(0);
    }

    /** The claim's log lines, oldest first. */
    public List<String> lines(Claim claim) {
        return lines(claim.getSheetId()).getOrDefault(claim.getId(), List.of());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as the front end reads it: the amount with two decimals, the date as yyyy-MM-dd,
 *  the status by name, the number as given when opened (1, 2, ... or <period>-<n> / X-<n>; null when it has none), the due fixed when
 *  settled with two decimals (null when it has none, so its due is worked out from the current rate), and who opened it
 *  (null until opened), whether its person's last statement bound it, and the figure it was bound to
 *  (null when not bound, or bound while it had none), whether it was bound to n/a (its rate had ended), and the number of the claim a correction corrects
 *  (null when it is not a correction), and the date its live figures round by (its own, or for a
 *  correction that of the claim it corrects), and the date it is due by, fixed when it was added, and its status log
 *  (see {@link ClaimLogStore}), oldest first, and whether it is deferred on the sheet's today (see
 *  {@link Claim#isDeferredOn}) and the date it was deferred until (null when never deferred), and how many proofs it has, and the number of the claim it was
 *  split off (null when it was not split off another), and whether it is a late entry (added while its period was soft-closed),
 *  and the last date it was reminded on (null when never reminded), and its external reference (null when it has none), and its tags, sorted (empty when it has none),
 *  and the reason it was voided with (null when none). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status, String number,
        String due, String openedBy, boolean stated, String statedDue, boolean statedNa, String corrects, String roundsBy,
        String dueBy, List<String> log, boolean deferred, String deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, String remindedOn, String ref, List<String> tags, String voidReason) {
    public static ClaimResponse from(Claim c) {
        return from(c, c.getDate());
    }

    public static ClaimResponse from(Claim c, Rounding rounding) {
        return from(c, rounding.date(c));
    }

    public static ClaimResponse from(Claim c, LocalDate roundsBy) {
        return new ClaimResponse(c.getId(), c.getPersonId(), c.getAmount().toPlainString(), c.getDate().toString(),
                c.getNote(), c.getStatus().name(), c.getNumber(),
                c.getSettledDue() == null ? null : c.getSettledDue().setScale(2).toPlainString(),
                c.getOpenedBy(), c.isStated(),
                c.getStatedDue() == null ? null : c.getStatedDue().setScale(2).toPlainString(), c.isStatedNa(),
                c.getCorrects(), roundsBy.toString(), c.getDueBy().toString(), List.of(),
                false, c.getDeferredUntil() == null ? null : c.getDeferredUntil().toString(), c.getProofs(),
                c.getSplitFrom(), c.isLateEntry(), c.getRemindedOn() == null ? null : c.getRemindedOn().toString(), c.getRef(),
                Tags.list(c.getTags()), c.getVoidReason());
    }

    /** The same claim with its status log lines, oldest first. */
    public ClaimResponse withLog(List<String> lines) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, lines, deferred, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason);
    }

    /** The same claim, deferred when OPEN and deferred until a date after the sheet's {@code today}. */
    public ClaimResponse on(LocalDate today) {
        boolean now = ClaimStatus.OPEN.name().equals(status) && deferredUntil != null && today != null
                && today.toString().compareTo(deferredUntil) < 0;
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, log, now, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason);
    }
}
-- A claim's status log: one entry per status it has had, oldest first (by id), each with the user who
-- made the change, the sheet's today then, and the claim's due as computed at that moment (n/a when
